#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int dados[] = {2, 0, 2, 3, 2, 0};
    int *cont = calloc(4, sizeof(int));
    for (int i = 0; i < 6; i++) {
        cont[dados[i]]++;
    }
    printf("%d%d%d%d\n", cont[0], cont[1], cont[2], cont[3]);
    free(cont);
    return 0;
}

