#include <stdio.h>
struct Conta { int saldo; };
void deposita(struct Conta c, int valor) {
    c.saldo += valor;
}
void saca(struct Conta *c, int valor) {
    c->saldo -= valor;
}
int main(void) {
    struct Conta conta = {100};
    deposita(conta, 50);
    saca(&conta, 30);
    printf("%d\n", conta.saldo);
    return 0;
}

