void aloca(int *p, int **q) {
    p = malloc(sizeof(int));
    *p = 7;
    *q = malloc(sizeof(int));
    **q = 9;
}
int main(void) {
    int x = 1, y = 2;
    int *r = &x, *s = &y;
    aloca(r, &s);
    printf("%d %d\n", *r, *s);
    return 0;
}

